const poetAnswers = Object.entries(poets).flatMap(([tier, names]) => names.split('|').filter(Boolean).map(name => a(name, tier)));
// A few widely known names appear in more than one regional source; keep one
// canonical review entry while retaining the first tier assigned above.
const uniquePoets = poetAnswers.filter((entry, index, list) => list.findIndex(candidate => candidate.answer === entry.answer) === index);
const krillion = () => a('Devangshi', 'krillion', ['gullu']);
const james = () => a('James', 'tooclever');
